-- Settings. Scope 'Shared' applies to every computer; 'Computer' to the named computer only (paths, logging).
CREATE TABLE IF NOT EXISTS "secureplus.Setting" (
    "Scope" TEXT NOT NULL,
    "ComputerName" TEXT NOT NULL,
    "SettingKey" TEXT NOT NULL,
    "Value" TEXT,
    "ModifiedBy" TEXT NOT NULL,
    "ModifiedAtUtc" TEXT NOT NULL,
    PRIMARY KEY ("Scope", "ComputerName", "SettingKey")
);
GO
-- Properties of this database: Mode (Production or Test), organization key check value, imports done.
CREATE TABLE IF NOT EXISTS "secureplus.DatabaseProperty" (
    "PropertyKey" TEXT NOT NULL,
    "Value" TEXT,
    "ModifiedBy" TEXT NOT NULL,
    "ModifiedAtUtc" TEXT NOT NULL,
    PRIMARY KEY ("PropertyKey")
);
GO
-- Named themes (light/dark mode, colours, typography) that workspaces use.
CREATE TABLE IF NOT EXISTS "secureplus.Theme" (
    "ThemeKey" TEXT NOT NULL,
    "Name" TEXT NOT NULL,
    "Description" TEXT,
    "PropertiesJson" TEXT NOT NULL,
    "IsSystem" INTEGER NOT NULL,
    "CreatedBy" TEXT NOT NULL,
    "CreatedAtUtc" TEXT NOT NULL,
    "ModifiedBy" TEXT,
    "ModifiedAtUtc" TEXT,
    PRIMARY KEY ("ThemeKey")
);
GO
CREATE UNIQUE INDEX IF NOT EXISTS "UX_Theme_Name" ON "secureplus.Theme" ("Name");
GO
-- The full customer profile (tenants, contacts, settings) as JSON; projected into cust.Customer, cust.Contact, cust.Tenant and cust.Engagement.
CREATE TABLE IF NOT EXISTS "secureplus.CustomerProfile" (
    "CustomerKey" TEXT NOT NULL,
    "Name" TEXT NOT NULL,
    "ProfileJson" TEXT NOT NULL,
    "Version" INTEGER NOT NULL,
    "IsSample" INTEGER NOT NULL,
    "IsArchived" INTEGER NOT NULL,
    "CreatedBy" TEXT NOT NULL,
    "CreatedAtUtc" TEXT NOT NULL,
    "ModifiedBy" TEXT NOT NULL,
    "ModifiedAtUtc" TEXT NOT NULL,
    PRIMARY KEY ("CustomerKey")
);
GO
-- Tenant client secrets, encrypted with the organization key (AES-256-GCM). The key is never stored in the database.
CREATE TABLE IF NOT EXISTS "secureplus.TenantSecret" (
    "SecretReference" TEXT NOT NULL,
    "CipherText" TEXT NOT NULL,
    "KeyId" TEXT NOT NULL,
    "CustomerKey" TEXT,
    "TenantKey" TEXT,
    "ExpiresAtUtc" TEXT,
    "CreatedBy" TEXT NOT NULL,
    "CreatedAtUtc" TEXT NOT NULL,
    "ModifiedBy" TEXT NOT NULL,
    "ModifiedAtUtc" TEXT NOT NULL,
    PRIMARY KEY ("SecretReference")
);
GO
-- Computers and users running Secure Plus Agent against this database.
CREATE TABLE IF NOT EXISTS "secureplus.ClientInstall" (
    "ComputerName" TEXT NOT NULL,
    "UserName" TEXT NOT NULL,
    "AppVersion" TEXT NOT NULL,
    "FirstSeenUtc" TEXT NOT NULL,
    "LastSeenUtc" TEXT NOT NULL,
    "HasOrganizationKey" INTEGER NOT NULL,
    PRIMARY KEY ("ComputerName", "UserName")
);
